  batchId ? '  Unmatched images: ' + cfg.intake_base_url + '/api/v1/batches/' + batchId + '/image-matches' : null,
  cfg.n8n_base_url ? '  n8n execution: ' + cfg.n8n_base_url + '/workflow/' + $workflow.id + '/executions/' + $execution.id
                   : '  n8n execution id: ' + $execution.id,
  'Time: ' + stamp(),
];
const countLine = (b) => 'Counts: files=' + b.total_files + ', images=' + b.total_images + ', products=' + b.total_products;
// ---- end helpers ----

// Expand Notifications - Code node (all items). Turns each branch result into 0..n individual email items.
const cfg = $('Validate Config').first().json;
const out = [];
for (const it of $input.all()) {
  for (const n of (it.json.notifications || [])) {
    out.push({ json: { ...n, run_id: it.json.run_id, notify_to: cfg.notify_to, notify_from: cfg.notify_from } });
  }
}
return out;
